X <- cbind(dati$x1, dati$x2)
X <- scale(X, center = TRUE, scale = FALSE)
K <- ncol(X)  # ora K = 2
```
:::



::: {.cell layout-align="center"}

```{.r .cell-code}
stan2_data <- list(
  N = nrow(dati),
  K = K,
  X = X,
  y = dati$y
)
```
:::



